package com.restaurant.billing.api;
import com.restaurant.billing.infrastructure.*; import com.restaurant.platform.api.*; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.time.*; import java.util.*;
@Service public class InvoiceAmendmentService { private static final Set<String> REASONS=Set.of("WRONG_ITEM","WRONG_QUANTITY","WRONG_PRICE","WRONG_DISCOUNT","CUSTOMER_CHANGED_ORDER","DUPLICATE_ITEM","WRONG_TAX","ITEM_NOT_SERVED","MANAGER_CORRECTION","OTHER"); private final InvoiceAmendmentRepository amendments; private final InvoiceRepository invoices; private final JdbcTemplate jdbc; private final PasswordEncoder encoder; private final AuditWriter audit;
 public InvoiceAmendmentService(InvoiceAmendmentRepository a,InvoiceRepository i,JdbcTemplate j,PasswordEncoder e,AuditWriter w){amendments=a;invoices=i;jdbc=j;encoder=e;audit=w;}
 @Transactional public Map<String,Object> request(UUID invoiceId,String reason,String notes){var p=TenantContext.require();if(p.isGuest())throw ApiException.forbidden("STAFF_ONLY","Staff only");String code=reason==null?"":reason.trim().toUpperCase();if(!REASONS.contains(code))throw ApiException.bad("AMENDMENT_REASON","Choose a valid amendment reason");if(notes==null||notes.isBlank())throw ApiException.bad("AMENDMENT_NOTES","Notes are required");var invoice=invoices.findById(invoiceId).orElseThrow(()->ApiException.notFound("INVOICE","Invoice not found"));if(!p.tenantId().equals(invoice.getTenantId())||p.outletIds()==null||!p.outletIds().contains(invoice.getOutletId()))throw ApiException.notFound("INVOICE","Invoice not found");if(!"GENERATED".equals(invoice.getStatus()))throw ApiException.conflict("AMENDMENT_STATE","Only an unpaid generated invoice can be amended");if(amendments.findByInvoiceId(invoiceId).stream().anyMatch(a->Set.of("REQUESTED","APPROVED").contains(a.getStatus())))throw ApiException.conflict("AMENDMENT_PENDING","This invoice already has a pending amendment");var a=new InvoiceAmendmentEntity();a.setTenantId(p.tenantId());a.setOutletId(invoice.getOutletId());a.setInvoiceId(invoiceId);a.setAmendmentNumber(amendments.findByInvoiceId(invoiceId).size()+1);a.setType("BILL_REVISION");a.setReasonCode(code);a.setReasonText(notes.trim());a.setRequestedBy(p.userId());a.setPreviousTotalPaise(invoice.getTotalPaise());amendments.save(a);audit.write("BILL_AMENDMENT_REQUESTED","INVOICE",invoiceId,"amendment="+a.getId()+" reason="+code);return Map.of("amendmentId",a.getId(),"status",a.getStatus());}
 @Transactional public Map<String,Object> approve(UUID id,UUID approverId,String password){var p=TenantContext.require();var a=amendments.findById(id).orElseThrow(()->ApiException.notFound("AMENDMENT","Not found"));var approvers=jdbc.query("select u.password_hash,u.status from users u join user_outlets uo on uo.user_id=u.id and uo.tenant_id=u.tenant_id and uo.outlet_id=? join user_roles ur on ur.user_id=u.id and ur.tenant_id=u.tenant_id join roles r on r.id=ur.role_id and r.tenant_id=u.tenant_id and r.code in ('OWNER','MANAGER','SHIFT_MANAGER') where u.id=? and u.tenant_id=?",(rs,n)->Map.<String,Object>of("hash",rs.getString(1),"status",rs.getString(2)),a.getOutletId(),approverId,p.tenantId());Map<String,Object> u=approvers.isEmpty()?null:approvers.getFirst();if(!p.tenantId().equals(a.getTenantId())||a.getRequestedBy().equals(approverId)||u==null||!"ACTIVE".equals(u.get("status"))||password==null||!encoder.matches(password,String.valueOf(u.get("hash")))||!"REQUESTED".equals(a.getStatus()))throw ApiException.unauthorized("Approval denied");String token=UUID.randomUUID().toString();a.setApprovedBy(approverId);a.setStatus("APPROVED");a.setApprovedAt(Instant.now());a.setApprovalTokenHash(encoder.encode(token));a.setApprovalExpiresAt(Instant.now().plusSeconds(300));amendments.save(a);audit.write("BILL_AMENDMENT_APPROVED","INVOICE",a.getInvoiceId(),"amendment="+id+" approver="+approverId);return Map.of("approvalToken",token,"expiresAt",a.getApprovalExpiresAt().toString());}}
